targets.root_selector:
([rows.{ 'model': model_name, 'gate': gate_decision, 'ic': ($ic := oos_ic; $lo := min_oos_ic_mean; $weak := weak_oos_ic_mean;
  $tier := $type($ic) != 'number' ? '' : $type($lo) = 'number' and $type($weak) = 'number' ? ($ic <= $lo ? 'bad' : $ic < $weak ? 'warn' : 'ok') : 'none';
  $tier ? $tier & '|' & $string($round($ic, 3)) : null), 'state': state,
      'min': 'IC 門檻 ' & $string(min_oos_ic_mean) & '（弱 ' & $string(weak_oos_ic_mean) & '，強 ' & $string(strong_oos_ic_mean) & '）', 'version': '版本 ' & champion_version,
      'run': '訓練 ' & gate_training_run_id & '（' & source_run_date & '）' }])

([($run := latest_monthly_run; $run.models.{ 'model': model_name, 'gate': gate_decision, 'ic': ($ic := oos_ic; $lo := min_oos_ic_mean; $weak := weak_oos_ic_mean;
  $tier := $type($ic) != 'number' ? '' : $type($lo) = 'number' and $type($weak) = 'number' ? ($ic <= $lo ? 'bad' : $ic < $weak ? 'warn' : 'ok') : 'none';
  $tier ? $tier & '|' & $string($round($ic, 3)) : null),
      'failed': $type(failed_gates) = 'array' and $count(failed_gates) > 0 ? $join(failed_gates, '、') : '—', 'state': state, 'live': $run.is_live ? '上線中' : '未上線',
      'run': '訓練 ' & $run.training_run_id & '（' & $run.source_run_date & '）', 'version': '版本 ' & version })])
